CREATE EXTENSION IF NOT EXISTS postgis;
CREATE TYPE user_role AS ENUM ('owner','admin','seller','warehouse','viewer');
CREATE TYPE product_type AS ENUM ('product','service');
CREATE TYPE sale_status AS ENUM ('draft','confirmed','cancelled');
CREATE TYPE payment_method AS ENUM ('cash','transfer','card','credit','other');
CREATE TYPE movement_type AS ENUM ('entry','sale','adjustment_in','adjustment_out','sale_reversal');
CREATE TYPE entry_status AS ENUM ('draft','confirmed','cancelled');
CREATE TABLE organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(160) NOT NULL, tax_id varchar(40), currency varchar(3) NOT NULL DEFAULT 'BOB', timezone varchar(60) NOT NULL DEFAULT 'America/La_Paz', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name varchar(120) NOT NULL, email varchar(180) NOT NULL, password_hash text NOT NULL, role user_role NOT NULL DEFAULT 'seller', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX users_email_uq ON users(email); CREATE INDEX users_org_idx ON users(organization_id);
CREATE TABLE refresh_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash varchar(64) NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX refresh_token_hash_uq ON refresh_tokens(token_hash); CREATE INDEX refresh_user_idx ON refresh_tokens(user_id);
CREATE TABLE units (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name varchar(80) NOT NULL, symbol varchar(12) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,symbol));
CREATE TABLE categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name varchar(100) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,name));
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), category_id uuid REFERENCES categories(id), unit_id uuid NOT NULL REFERENCES units(id), sku varchar(50) NOT NULL, name varchar(160) NOT NULL, description text, type product_type NOT NULL DEFAULT 'product', sale_price numeric(14,2) NOT NULL DEFAULT 0, cost_price numeric(14,2) NOT NULL DEFAULT 0, min_stock numeric(14,3) NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,sku));
CREATE INDEX products_org_name_idx ON products(organization_id,name);
CREATE TABLE customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), document varchar(40), name varchar(160) NOT NULL, phone varchar(30), email varchar(180), address text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX customers_org_name_idx ON customers(organization_id,name);
CREATE TABLE warehouses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name varchar(120) NOT NULL, code varchar(20) NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,code));
CREATE TABLE stocks (organization_id uuid NOT NULL REFERENCES organizations(id), warehouse_id uuid NOT NULL REFERENCES warehouses(id), product_id uuid NOT NULL REFERENCES products(id), quantity numeric(14,3) NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(warehouse_id,product_id)); CREATE INDEX stocks_org_idx ON stocks(organization_id);
CREATE TABLE document_sequences (organization_id uuid NOT NULL REFERENCES organizations(id), document_type varchar(30) NOT NULL, year integer NOT NULL, current_value integer NOT NULL DEFAULT 0, PRIMARY KEY(organization_id,document_type,year));
CREATE TABLE sales (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), customer_id uuid REFERENCES customers(id), warehouse_id uuid NOT NULL REFERENCES warehouses(id), number varchar(30) NOT NULL, sold_at timestamptz NOT NULL DEFAULT now(), status sale_status NOT NULL DEFAULT 'confirmed', subtotal numeric(14,2) NOT NULL, discount numeric(14,2) NOT NULL DEFAULT 0, total numeric(14,2) NOT NULL, notes text, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,number)); CREATE INDEX sales_org_date_idx ON sales(organization_id,sold_at);
CREATE TABLE sale_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sale_id uuid NOT NULL REFERENCES sales(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES products(id), description varchar(180) NOT NULL, quantity numeric(14,3) NOT NULL, unit_price numeric(14,2) NOT NULL, discount numeric(14,2) NOT NULL DEFAULT 0, total numeric(14,2) NOT NULL);
CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), sale_id uuid NOT NULL REFERENCES sales(id), amount numeric(14,2) NOT NULL, method payment_method NOT NULL, reference varchar(100), paid_at timestamptz NOT NULL DEFAULT now(), created_by uuid NOT NULL REFERENCES users(id));
CREATE TABLE stock_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), warehouse_id uuid NOT NULL REFERENCES warehouses(id), number varchar(30) NOT NULL, source varchar(80) NOT NULL DEFAULT 'purchase', reference varchar(100), received_at timestamptz NOT NULL DEFAULT now(), status entry_status NOT NULL DEFAULT 'confirmed', notes text, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,number));
CREATE TABLE stock_entry_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entry_id uuid NOT NULL REFERENCES stock_entries(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES products(id), quantity numeric(14,3) NOT NULL, unit_cost numeric(14,2) NOT NULL DEFAULT 0);
CREATE TABLE inventory_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), warehouse_id uuid NOT NULL REFERENCES warehouses(id), product_id uuid NOT NULL REFERENCES products(id), type movement_type NOT NULL, quantity numeric(14,3) NOT NULL, unit_cost numeric(14,2), reference_type varchar(40) NOT NULL, reference_id uuid NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), created_by uuid NOT NULL REFERENCES users(id)); CREATE INDEX movements_product_date_idx ON inventory_movements(organization_id,product_id,occurred_at);
